import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;

    static long qp(long p, long x) {
        long ans = 1;
        for (int i = 0; i < x; ++i) {
            ans = (ans * p) % MOD;
        }
        return ans;
    }

    static long solve(long p, long k) {
        if (k <= 1) {
            return qp(p, p - 1 + k);
        }
        int ord = 1;
        long now = k;
        while (now != 1) {
            now = (now * k) % p;
            ++ord;
        }
        return qp(p, (p - 1) / ord);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        System.out.println(solve(p, k));
        sc.close();
    }
}
